void irq_domain_associate_many ( struct irq_domain * domain , unsigned int irq_base , irq_hw_number_t hwirq_base , int count ) { struct device_node * of_node ; int i ; pr_debug ( "%s(%s, irqbase=%i, hwbase=%i, count=%i)\n" , __func__ , of_node_full_name ( of_node ) , irq_base , ( int ) hwirq_base , count ) ; for ( i = 0 ; i < count ; i ++ ) { irq_domain_associate ( domain , irq_base + i , hwirq_base + i ) ; } } 